Below it is also expressed in degrees latitude overfilled.


Code
eco_data |&gt;
  filter(present == 1) |&gt;
  group_by(lon, lat) |&gt;
  summarise(
    tmin = min(tmin, na.rm = TRUE),
  ) |&gt;
  mutate(
    below_lowest_ctmin = tmin &lt; min(ctmin_data$ctmin, na.rm = TRUE),
    below_avg_ctmin = tmin &lt; mean(ctmin_data$ctmin, na.rm = TRUE),
    below_highest_ctmin = tmin &lt; max(ctmin_data$ctmin, na.rm = TRUE),
    below_0 = tmin &lt; 0
  ) |&gt;
  ungroup() |&gt;
  pivot_longer(
    cols = c(below_lowest_ctmin, below_avg_ctmin, below_highest_ctmin, below_0),
    names_to = "category",
    values_to = "below_threshold"
  ) |&gt;
  filter(below_threshold) |&gt;
  group_by(category) |&gt;
  filter(lat == min(lat, na.rm = TRUE)) |&gt;
  slice(1) |&gt;
  ungroup() |&gt;
  mutate(
    degrees_overfill = max(caro_range_points$lat, na.rm = TRUE) - lat
  ) |&gt;
  mutate(
    category = case_when(
      category == "below_lowest_ctmin" ~ paste("Lowest CTmin - ", round(min(ctmin_data$ctmin, na.rm = TRUE), 2), "°C"),
      category == "below_avg_ctmin" ~ paste("Average CTmin - ", round(mean(ctmin_data$ctmin, na.rm = TRUE), 2), "°C"),
      category == "below_highest_ctmin" ~ paste("Maximum CTmin - ", round(max(ctmin_data$ctmin, na.rm = TRUE), 2), "°C"),
      category == "below_0" ~ paste("0°C (Freezing Threshold)")
    )
  ) |&gt;
  select(category, degrees_overfill) |&gt;
  rename(
    "Threshold" = category,
    "Degrees Overfill" = degrees_overfill
  ) |&gt;
  kable() |&gt;
  kable_styling(
    full_width = FALSE,
    position = "center"
  )





